import React, { useEffect, useMemo, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import useAccessControl from '../access/hooks/useAccessControl';
import useAutomations from './hooks/useAutomations';
import { AUTOMATION_TRIGGERS } from './model';
import AutomationRuleModal from './components/AutomationRuleModal';
import './AutomationsWorkspace.scss';

function formatTime(value) { const d = new Date(value); return Number.isNaN(d.getTime()) ? '—' : d.toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}); }

export default function AutomationsWorkspace() {
  const access = useAccessControl();
  const automations = useAutomations();
  const [params, setParams] = useSearchParams();
  const [editing, setEditing] = useState(null);
  const canManage = access.can('automations.manage');
  useEffect(() => { const template=params.get('template'); if(template&&canManage){ const next=automations.fromTemplate(template); if(next){setEditing(next); const copy=new URLSearchParams(params);copy.delete('template');setParams(copy,{replace:true});}} },[automations,canManage,params,setParams]);
  const recentLog = useMemo(()=>automations.log.slice(0,8),[automations.log]);
  const newRule = () => ({ id:`automation-${Date.now().toString(36)}`, name:'Новая автоматизация', description:'', enabled:true, trigger:'review.received', conditions:{ratingMin:1,ratingMax:3,platforms:[],reasons:[]}, actions:['notify'], priority:'high' });
  return <div className="automation-page"><section className="automation-hero"><div><span className="automation-eyebrow"><i/> AUTOMATION ENGINE</span><h1>Репутация работает<br/><em>по правилам, а не вручную.</em></h1><p>Бизнес Щит превращает негатив, риск SLA и задержки согласования в конкретные действия команды.</p><div className="automation-hero__actions">{canManage?<button type="button" onClick={()=>setEditing(newRule())}>+ Новое правило</button>:null}<button type="button" className="is-secondary" disabled={automations.running} onClick={automations.runNow}>{automations.running?'Проверяем…':'Проверить правила сейчас'}</button></div></div><div className="automation-orbit"><div className="automation-orbit__core"><strong>{automations.metrics.active}</strong><span>активно</span></div><i className="is-one"/><i className="is-two"/><i className="is-three"/><b>AUTO</b></div></section><section className="automation-kpis"><article><span>Правил</span><strong>{automations.metrics.total}</strong><small>в рабочем пространстве</small></article><article><span>Активно</span><strong>{automations.metrics.active}</strong><small>следят за событиями</small></article><article><span>Срабатываний</span><strong>{automations.metrics.runs}</strong><small>в журнале выполнения</small></article><article className={automations.metrics.errors?'is-danger':''}><span>Ошибок</span><strong>{automations.metrics.errors}</strong><small>{automations.metrics.errors?'требуют проверки':'всё штатно'}</small></article></section><section className="automation-layout"><div className="automation-rules"><header><div><span>RULES</span><h2>Рабочие сценарии</h2></div><small>Идемпотентное выполнение · без повторных задач</small></header>{automations.rules.map((rule,index)=><article className={`automation-rule ${rule.enabled?'is-enabled':''}`} key={rule.id} style={{'--delay':`${index*45}ms`}}><div className="automation-rule__rail"><i/></div><div className="automation-rule__main"><div className="automation-rule__title"><span>{AUTOMATION_TRIGGERS.find((item)=>item.id===rule.trigger)?.label||rule.trigger}</span><strong>{rule.name}</strong><p>{rule.description||'Сценарий автоматической реакции на событие.'}</p></div><div className="automation-rule__flow"><span>СОБЫТИЕ</span><b>→</b><span>{rule.conditions.ratingMin}–{rule.conditions.ratingMax}★{rule.conditions.platforms.length?` · ${rule.conditions.platforms.join(', ')}`:''}</span><b>→</b><span>{rule.actions.length} действий</span></div></div><div className="automation-rule__actions"><label className="automation-switch"><input type="checkbox" checked={rule.enabled} disabled={!canManage} onChange={(e)=>automations.toggle(rule.id,e.target.checked)}/><span/></label>{canManage?<button type="button" onClick={()=>setEditing(rule)}>Настроить</button>:null}{canManage&&!rule.systemTemplate?<button type="button" className="is-danger" onClick={()=>automations.remove(rule.id)}>Удалить</button>:null}</div></article>)}</div><aside className="automation-log"><header><span>EXECUTION LOG</span><h2>Последние действия</h2><i>LIVE</i></header>{recentLog.length?recentLog.map((item,index)=><article key={item.id} className={`is-${item.status}`} style={{'--delay':`${index*45}ms`}}><span className="automation-log__status">{item.status==='success'?'✓':'!'}</span><div><strong>{item.ruleName}</strong><p>{item.targetLabel||item.trigger}</p><small>{formatTime(item.createdAt)} · {(item.effects||[]).join(' · ')||item.trigger}</small></div></article>):<div className="automation-empty"><strong>Журнал пока пуст</strong><span>После первого события здесь появится цепочка выполненных действий.</span></div>}</aside></section><AutomationRuleModal open={Boolean(editing)} rule={editing} onClose={()=>setEditing(null)} onSave={automations.save}/></div>;
}
